CREATE TABLE IF NOT EXISTS notification_outbox(id TEXT PRIMARY KEY,alert_id TEXT NOT NULL REFERENCES workflow_alerts(id),recipient_id TEXT NOT NULL REFERENCES users(id),channel TEXT NOT NULL DEFAULT 'email',status TEXT NOT NULL DEFAULT 'pending',attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,sent_at TEXT,UNIQUE(alert_id,recipient_id,channel));
